public protocol EngineProtocol: AnyObject, Sendable {
    
    /**
     * RAW cache misses return pending immediately; PreviewReady signals completion.
     */
    func embeddedPreview(imageId: String, maxPx: UInt32) throws  -> PreviewResponse
    
    func getRecipe(imageId: String) throws  -> String
    
    func indexFolder(path: String) throws  -> FolderHandle
    
    func listImages(query: ImageQuery) throws  -> [ImageSummary]
    
    func setEventListener(listener: EngineEventListener?) 
    
    func setRecipeJson(imageId: String, json: String) throws 
    
    func setSelection(imageId: String, selection: Selection) throws 
    
    /**
     * Opens (without creating) the library document at `path`, conventionally
     * `<folder>/library.json`, and aligns the catalog's keyword hierarchy.
     */
    func openLibrary(path: String) throws  -> LibraryStore
    
    /**
     * Opens a develop session on an indexed RAW image. Blocking (decodes the
     * raw): call off the main thread. One session per visible image.
     */
    func openDevelopSession(imageId: String) throws  -> DevelopSession
    
    /**
     * Reads (a temporary copy of) the catalog. Blocking: call off the main thread.
     */
    func openLrcat(path: String) throws  -> LrcatImport
    
    /**
     * Recursive folder queue over already-indexed images (call `index_folder`
     * first). The library defaults to `<folder>/library.json`. Auto-advance is
     * off; hosts move the cursor with `set_current`/navigation.
     */
    func openCullSession(folder: String) throws  -> CullSession
    
    /**
     * Filtered queue. Zero limit means all matches. Call `set_library` before
     * basket operations.
     */
    func openCullSessionForQuery(query: ImageQuery) throws  -> CullSession
    
    /**
     * Stores the latest value of an AI signal (e.g. "focus", "closed_eyes").
     * Producers are ML jobs; the app uses it only for synthetic test scores.
     */
    func setScore(imageId: String, signal: String, value: Double, model: String) throws 
    
}
