         * that redo would reapply).
         */applied: Bool, isHead: Bool, 
        /**
         * False when the step has been turned off with a step toggle.
         */enabled: Bool, 
        /**
         * The step is itself a toggle of another step (shown as such, not toggleable).
         */toggles: UInt64?) {
        self.id = id
        self.label = label
        self.author = author
        self.group = group
